data = [(x, 2 * x + 1) for x in range(12)]

def model_linear(x):
    return 2 * x + 1

def model_constant(x):
    return 12

def mean_absolute_error(model, fold):
    errors = [abs(model(x) - y) for x, y in fold]
    return sum(errors) / len(errors)

def k_fold_split(data, k):
    folds = [[] for _ in range(k)]
    for i, item in enumerate(data):
        folds[i % k].append(item)
    return folds

folds = k_fold_split(data, k=4)

for name, model in [("linear", model_linear), ("constant", model_constant)]:
    fold_scores = [mean_absolute_error(model, fold) for fold in folds]
    avg_score = sum(fold_scores) / len(fold_scores)
    print(f"modelo={name} fold_mae={[round(s, 3) for s in fold_scores]} promedio={avg_score:.3f}")

scores = {}
for name, model in [("linear", model_linear), ("constant", model_constant)]:
    fold_scores = [mean_absolute_error(model, fold) for fold in folds]
    scores[name] = sum(fold_scores) / len(fold_scores)

best_model = min(scores, key=scores.get)
print(f"Modelo seleccionado: {best_model}")
